INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein rekursiver Algorithmus immer langsamer als ein iterativer?', 2, '[{"text": "Nein", "correct": true, "because": "Kontextabhängig, z. B. bei Bäumen effizient"}, {"text": "Ja", "correct": false, "because": "Überhead nicht immer entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem rekursiven Algorithmus?', 3, '[{"text": "Elegante Problemlösung", "correct": true, "because": "Vereinfacht komplexe Strukturen"}, {"text": "Maximale Speicherauslastung", "correct": false, "because": "Nicht primär"}, {"text": "Schnellste Ausführung", "correct": false, "because": "Effizienz variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst Rekursion besonders gut?', 5, '[{"text": "Baumdurchläufe", "correct": true, "because": "Natürlich für Hierarchien"}, {"text": "Teile-und-Herrsche", "correct": true, "because": "Zerlegt Probleme"}, {"text": "Lineare Listen", "correct": false, "because": "Iteration meist besser"}, {"text": "Datenkompression", "correct": false, "because": "Andere Ansätze üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rekursion braucht eine Abbruchbedingung. b) Sie ist immer speicherintensiv.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicher abhängig von Tiefe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung eines rekursiven Algorithmus?', 4, '[{"text": "Abbruchbedingung", "correct": false, "because": "Verhindert Endlosschleifen"}, {"text": "Stack-Tiefe", "correct": false, "because": "Risiko von Overflow"}, {"text": "Farbanimation", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Rekursion auch bei flachen Strukturen sinnvoll ist?', 2, '[{"text": "Nein", "correct": true, "because": "Iteration meist effizienter"}, {"text": "Ja", "correct": false, "because": "Rekursion überflüssig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe löse ich typischerweise mit Rekursion?', 3, '[{"text": "Faktoriellen berechnen", "correct": true, "because": "Klassisches Beispiel"}, {"text": "Lineare Suche", "correct": false, "because": "Iteration besser"}, {"text": "Datenkomprimierung", "correct": false, "because": "Andere Methoden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Rekursion nützlich?', 5, '[{"text": "Selbstaufruf", "correct": true, "because": "Zerlegt Probleme"}, {"text": "Abbruchbedingung", "correct": true, "because": "Beendet Rekursion"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Statische Größe", "correct": false, "because": "Nicht maßgeblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Rekursion ist bei Bäumen ideal. b) Sie ist immer stack-intensiv. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Stack abhängig von Tiefe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen rekursiven Algorithmus?', 4, '[{"text": "Rekursionsbasis", "correct": false, "because": "Stoppt Rekursion"}, {"text": "Selbstaufruf", "correct": false, "because": "Kern der Rekursion"}, {"text": "Grafische Ausgabe", "correct": true, "because": "Nicht funktional nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Rekursion ohne Abbruchbedingung möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Führt zu Endlosschleifen"}, {"text": "Ja", "correct": false, "because": "Unpraktisch und fehleranfällig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme eignen sich für rekursive Baumdurchläufe?', 4, '[{"text": "Inorder-Traversal", "correct": true, "because": "Sortierte Ausgabe"}, {"text": "Preorder-Traversal", "correct": true, "because": "Hierarchische Verarbeitung"}, {"text": "Lineare Addition", "correct": false, "because": "Iteration besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Rekursion immer zu Stack-Overflow führt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei tiefer Rekursion"}, {"text": "Ja", "correct": false, "because": "Abhängig von Implementierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Aspekt priorisiere ich bei einem rekursiven Algorithmus?', 3, '[{"text": "Klarheit der Basis", "correct": true, "because": "Verhindert Fehler"}, {"text": "Minimale Laufzeit", "correct": false, "because": "Sekundär"}, {"text": "Hohe Speichergröße", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rekursion ist für Divide-and-Conquer ideal. b) Sie ist für flache Schleifen besser.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flache Schleifen für Iteration"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Rekursion bei Baumstrukturen?', 5, '[{"text": "Natürliche Hierarchie", "correct": true, "because": "Spiegelt Struktur wider"}, {"text": "Kürzerer Code", "correct": true, "because": "Weniger komplex als Iteration"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Oft langsamer"}, {"text": "Geringerer Speicher", "correct": false, "because": "Stack-intensive"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem rekursiven Algorithmus unwichtig?', 3, '[{"text": "Rekursionstiefe", "correct": false, "because": "Beeinflusst Stack"}, {"text": "Abbruchbedingung", "correct": false, "because": "Kern der Logik"}, {"text": "Farbkodierung", "correct": true, "because": "Kein funktionaler Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Rekursion bei linearen Daten effizient sein?', 3, '[{"text": "Nein", "correct": true, "because": "Iteration meist schneller"}, {"text": "Ja", "correct": false, "because": "Overhead überflüssig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Rekursion für Fibonacci-Zahlen sinnvoll ist?', 2, '[{"text": "Nein", "correct": true, "because": "Exponentielle Zeit bei Naivität"}, {"text": "Ja", "correct": false, "because": "Mit Memoization besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Ansatz wähle ich für einen rekursiven Baumdurchlauf?', 4, '[{"text": "Postorder", "correct": true, "because": "Verarbeitet Kinder vor Eltern"}, {"text": "Lineare Suche", "correct": false, "because": "Nicht baumorientiert"}, {"text": "Bubble Sort", "correct": false, "because": "Sortierung, kein Durchlauf"}]');
